import {instructionPDF} from './manual.js';
import {VERSION,BUILD_ID} from './version.js';
import {feedManifest,feedGuide,rodCSV,feedHardwareCSV} from './feed.js';
import {binarySTL,volume,zip,connectionCoupon,packedPlateMesh,hardwareSchedule,hubMountGrip,JOINT} from './geometry.js';
export function scadSource(m,kernel){
 const serial=mesh=>JSON.stringify(mesh.v.map(v=>v.map(x=>+x.toFixed(6))));
 let text='// PETAL geometry snapshot. Regenerate in PETAL after changing dimensions.\n// Parameters: '+JSON.stringify(m.p)+'\npart = "assembly"; // [assembly,'+m.parts.map(p=>p.id).join(',')+']\nprinting = true;\n';
 m.parts.forEach((p,i)=>{
  text+=`module assembly_${i}(){polyhedron(points=${serial(p.mesh)},faces=${JSON.stringify(p.mesh.f.map(f=>[...f].reverse()))},convexity=20); }\n`;
  text+=`module print_${i}(){polyhedron(points=${serial(p.output)},faces=${JSON.stringify(p.output.f.map(f=>[...f].reverse()))},convexity=20); }\n`;
  text+=`if(part=="${p.id}"){if(printing)print_${i}();else assembly_${i}();}\n`;
 });
 text+='if(part=="assembly"){\n';
 for(const inst of m.instances)text+=`rotate([0,0,${inst.a*180/Math.PI}])assembly_${m.parts.indexOf(inst.part)}();\n`;
 return text+'}\n';
}


export function reflectorGuide(m){return `# Reflector surface and RF setup

PETAL prints a support structure. The frequency, feed, conductive finish and mount determine whether the assembled system works as an antenna. There is no measured gain or RF rating for this design.

## Recommended first article: a continuous foil face

Use a thin aluminum foil tape whose adhesive is explicitly conductive, for example 3M 1170. 3M 1181 copper foil tape is another conductive-adhesive option, but copper adds more mass. These are examples of material construction, not qualified PETAL finishes or outdoor lifetime guarantees. Ordinary HVAC tape may have insulating adhesive; overlapping it does not guarantee electrical contact between strips.

Sources: https://www.3m.com/3M/en_US/p/d/b5005158003/ and https://www.3m.com/3M/en_US/p/d/b5005158005/

1. Print an adhesion/coating scrap from the actual filament. Check the tape and any primer after a warm hold and gentle peel. Do not assume adhesion to an injection-molded plastic transfers to a printed surface.
2. Dry-fit, mark and measure the uncoated assembly. Complete heat-setting before applying the conductive finish. Lightly remove burrs; do not sand the parabola into a different shape.
3. Apply narrow strips to each front petal, burnishing gently from the center outward. Start around 10–20 mm strip width and reduce it where compound curvature causes wrinkles. Avoid stretching foil tight across gaps or unsupported holes. Keep overlaps small and consistent; record their height if operating at short wavelengths.
4. Mask flange datums, bearing faces and bores. Cover the central hub front with the same finish. Do not bridge a pocket with foil that a screw will tear during service.
5. Assemble and align first. Bridge seams with removable strips afterward, without pulling petals together. Remove these strips before disassembly. Do not use a continuous skin as an alignment clamp.
6. With power disconnected, check foil-to-foil continuity across strips, hub and seams at many points. Compare against the meter’s shorted-lead baseline; intermittent or unexpectedly high resistance needs investigation. DC continuity is a useful workmanship check, not proof of RF efficiency.
7. Recheck surface shape, adhesion and continuity after thermal cycling and repeated assembly. Corrosion, water ingress and differential expansion require an outdoor finishing plan. Do not assume a generic clearcoat is RF-neutral or compatible with the tape. Keep a specular foil-covered dish pointed away from the Sun during handling; concentrated sunlight near the focus can heat the feed or fixture.

## Conductive paints

A specified silver or silver-coated-copper conductive coating is an alternative when foil wrinkles are unacceptable. Examples are MG Chemicals 842AR and 843AR. They are designed as conductive shielding coatings; that does not establish antenna-reflector performance on PETAL. Follow the current technical data and safety sheets, verify dry-film thickness and sheet resistance, and test solvent/primer compatibility on the actual ASA, ABS or PCTG print. Solvent attack, shrinkage and poor adhesion can ruin surface accuracy. Metallic-looking craft paint, ordinary graphite paint and carbon-filled filament are not automatically suitable low-loss reflectors.

Sources: https://mgchemicals.com/products/conductive-paint/conductive-acrylic-paints/silver-conductive-paint/ and https://mgchemicals.com/products/conductive-paint/conductive-acrylic-paint/copper-conductive-paint/

## Perforations and mesh

This version has no perforation mode. Conductive mesh must be chosen for the intended wavelength; openings, wire size, conductivity and surface accuracy all matter. Do not equate percent open area with gain loss. A continuous foil covering over printed holes needs support against sagging and will largely block airflow. Reference: https://www.gmrt.ncra.tifr.res.in/doc/WEBLF/LFRA/node173.html

## Feed and alignment

This configuration has focal length ${m.focal.toFixed(2)} mm from the parabola vertex, dish depth ${m.depth.toFixed(2)} mm, and rim half-angle ${(2*Math.atan(1/(4*m.p.fd))*180/Math.PI).toFixed(2)} degrees as seen from the focus. The vertex is the extrapolated center of the parabola, not the rear hub surface or rim plane. Place the feed phase center at the focus and match its illumination to that rim angle. Provide rigid, adjustable axial/lateral positioning and polarization adjustment. Route and strain-relieve the cable so it cannot move the feed. ${m.feed?'Support parts and rod cuts are included; see FEED-SUPPORT.md. The RF feed and its specific adapter remain separate.':'Enable the optional rod support to generate mounting parts and rod cuts. The RF feed is not supplied.'}

Choose an operating band before setting surface tolerances. As an engineering starting budget, allocate no more than wavelength/50 RMS to structural/assembly error, then account separately for finish, feed and pointing. This is a proposed test criterion, not a verified capability. Use the shortest wavelength in a band. Measure at several azimuths and elevations; systematic seam steps and defocus need attention beyond a single RMS number.

Check feed return loss if equipment is available, but also compare received level and beam pattern against a known reference with fixed polarization, cable, receiver gain and geometry. Good impedance matching alone does not prove reflector gain. Use a suitable far-field range or a properly characterized near-field method, rather than a nearby transmitter of unknown geometry. RF background: https://www.cv.nrao.edu/~sransom/web/Ch3.html

## Material references

ASA: outdoor UV/temperature suitability, with significant warping risk unless the printer environment is controlled: https://help.prusa3d.com/article/asa_1809
PCTG: manufacturer-specific material data; heat-distortion temperature is not a continuous precision-service limit: https://fiberlogy.com/en/fiberlogy-filaments/pctg/
Inserts and plastic creep: https://www.spirol.com/resources/white-papers/how-to-properly-mate-compression-limiters-and-threaded-inserts-in-plastic-assemblies/
`;}
export function manifest(m){return{generator:'PETAL '+VERSION+' prototype',build:BUILD_ID,units:'mm',interface_revision:JOINT.revision,parameters:m.p,segmentation:m.layout,ring_phases_degrees:m.ringPhases.map(a=>a*180/Math.PI),root_fasteners:m.p.rootThrough?'M4 through bolts and nuts':'M4 blind inserts',mount_fasteners:m.p.mountThrough?'M4 through / Ø4.6':'M4 blind inserts',hub_front:m.p.hubFlat?'flat':'curved',manual_packing:!!m.manualPacking,focus_mm:m.focal,depth_mm:m.depth,center_hole_mm:30,mount_bcd_mm:60,hardware:hardwareSchedule(m),feed_support:feedManifest(m),parts:m.parts.map(p=>({file:p.id+'_qty-'+p.qty+'.stl',quantity:p.qty,dimensions_mm:p.dim,volume_cm3:volume(p.mesh)/1000,orientation:p.kind==='panel'?'flat radial flange down':'use exported orientation',bed_rotation_degrees:p.bedRotation})),packed_plates:m.plates.map(p=>p.placements.map(x=>({copy:x.copy,part:x.part.id,yaw:x.yaw,x:x.x,y:x.y}))),limitations:['Unprinted engineering prototype; no load or RF rating.','Regenerate the complete kit; incompatible with earlier dish joints and hubs.','Packing uses geometry bounds; add at most 3 mm brims between parts or disable packing.','Facets approximate only the underside; RF face remains a tessellated parabola.']};}
export function guideSections(m){return[
{title:'New interface · print a test first',body:'PETAL uses integral flanges and one rear hub, interface revision '+JOINT.revision+'. Do not mix older petals, saddles, caps or hubs with this kit. The first article is a geometric prototype, not a validated antenna or outdoor load-bearing structure. Start with two copies of FIT_TEST/seam-strip-print-two.stl in their exported orientations. These are sections of the real petal, including both flange edges, one screw position and the locating key. They intentionally retain the petal width so the upper flange prints in the same orientation as the full part. They do not test full-length warping or the hub.'},
{title:'Materials and side printing',body:'Use dry PETG for an indoor fit article; use ASA for outdoor trials only with a controlled enclosure and a verified material profile. PLA can establish fit but is a poor choice for a warm, sunlit dish. Start with a 0.4 mm nozzle, 0.2 mm layers and at least four perimeters; preview thin walls and use locally solid flange pads and root bosses. Exported petals stand on their flat radial flange; the curved underside is sideways. A full-depth upper-flange gusset, ramped inner end and bed-connected root boss reduce broad unsupported projections. Curved is the default. Optional small tangent-plane underside facets add material without changing the RF face. Add a 3–6 mm brim for full petals and check adhesion. Packed copies have 6 mm between bounding boxes: limit individual brims to 3 mm or disable packing. Avoid sequential-by-object printing unless the slicer confirms toolhead clearance. The upper flange, bores and key recesses still require layer-preview inspection; pointed roofs reduce unsupported spans but are not a universal support-free guarantee. Use localized supports if your slicer/material requires them. Hub prints flat rear down.'+(m.p.seamJoint?' Seam clips print flat as exported, so the arms flex along the layers; print them in the same material as the dish (ASA-GF holds up outdoors) and use the fit-test clips to set the squeeze.':'')},
{title:'Fit and fasteners',body:`Remove first-layer flare only from mating edges; the mating faces are flat, with no keys. ${[`Every seam bolt clamps between two flat Ø10 mm seats square to the bolt, one on each flange; the nut is loose, not captured. Test the real M3 hardware on the coupon before printing the whole dish.`,`Seams are held by printed snap clips: solid blocks with a channel that snap straight up over both flange pads from behind. A ${m.p.clipTooth.toFixed(1)} mm tooth on each jaw drops into a matching notch across the pad face; its flat underside is the catch. The clips squeeze ${m.p.clipFit.toFixed(2)} mm per side, and they also line the two petals up. FIT_TEST has clips one step looser and tighter: try all three on the strips and set the squeeze to the one that snaps on firmly without whitening.`,`Each station takes either an M3 bolt (flat seats on both flanges, loose nut) or a printed snap clip (its teeth drop into the notches across the pads). FIT_TEST has clips one step looser and tighter than the ${m.p.clipFit.toFixed(2)} mm squeeze: try them on the strips before printing the set.`][m.p.seamJoint]} ${m.p.rootThrough?'Petal roots take M4 through bolts: each root has a Ø9.6 mm flat seat recessed into the front so the head and washer sit below the reflecting face.':'Petal roots take blind heat-set inserts, so the reflecting face above them stays closed.'} ${m.p.mountThrough?'The hub mount bolts pass fully through, with Ø10 mm seats 5 mm deep in the hub front for the washers and nuts.':'The hub mount uses blind heat-set inserts.'} ${m.p.rootThrough&&m.p.mountThrough?'No heat-set inserts are needed.':`Insert pockets are Ø${m.p.insertDiameter.toFixed(2)} × 7 mm for short M4 inserts, maximum 6 mm long, seated 0.5 mm below the entry. Insert pilot requirements depend on the exact insert and filament: verify the supplier specification and use an insert scrap before installation. Heat-set while supporting the boss, never by loading the RF face. Let it cool fully.`} The hub front is ${m.p.hubFlat?'flat at the height of the petal roots':'curved, following the dish'}.`},
{title:'Assembly without pulling in warp',body:(m.p.staggerRings&&m.layout.rows>1?'Adjacent rings are offset by half a petal, making three-panel junctions. Assemble the innermost ring loosely, then add outer segments one at a time, sliding radially inward. Each outer segment connects to two inner neighbors across paired polygon facets. Mating faces are flat: support the front profile in a jig and align both mating pads before snugging the screws. Do not bolt complete rings together under force. ':'If petals are segmented, join each radial strip first using its integral cross-flanges. Then bring complete petals together by sliding radially inward from outside the rim; ')+ ' the flat mating faces meet as the edges approach. Keep all fasteners loose. The final petal also approaches radially; do not try to snap it into a closed ring from the front. Keys locate and flange pads establish contact; bolts retain. Place the shape in a measured support jig, check seam steps, then lightly snug opposite seams in several passes. Install the rear hub after the petal ring closes freely. Never use bolts to bend a warped petal until its seam disappears. Reprint or correct the process if faces do not sit flat, pads do not seat or the final petal needs force. Full-length flanges increase stiffness but thermal shrinkage and accumulated print error still require measurement.'},
{title:'Hardware and access',body:(m.p.seamJoint!==1?'Use M3 × 16 socket-head seam screws with a 0.5 mm washer under the head and under the nut. Each nut sits loose on a flat seat; hold it with a 5.5 mm nut driver or wrench and drive the screw from the other side. ':'')+(m.p.seamJoint?'To fit a clip, push it straight up over both flanges from behind until both teeth snap into the notches; it takes a firm push or a light mallet tap. To remove one, spring one jaw outward with a flat screwdriver until its tooth clears the notch, then pull the clip down. Clips hold the seam closed but do not clamp it like a bolt; '+(m.p.seamJoint===2?'use bolts at stations that need a firm clamp. ':'for a firm clamp, regenerate with bolts or both. '):'')+'Work from behind the dish, and verify tool access before fitting rods. '+(m.p.rootThrough?'Root screws are M4 × 20 socket heads from the front, head and washer in the recessed seat, with a washer and nut on the hub rear face. ':'M4 × 12 root screws go from the hub rear, with one 1 mm washer, into the petal inserts; nominal 5 mm entry. ')+(m.p.mountThrough?`The external mount keeps the clear 30 mm center hole and has four Ø4.6 mm through bores on a 60 mm bolt circle. Put the heads behind the adapter and the washers and nuts in the Ø10 mm front seats (washers 9 mm OD or less). Select screw length as ${Math.ceil(hubMountGrip(m.p)+6.3)} mm plus the adapter thickness, rounded up. Install front hardware before applying removable foil patches; keep bores and hardware accessible.`:'The external mount keeps a clear 30 mm center hole and four blind M4 inserts on a 60 mm bolt circle; select mount screw length from the actual adapter stack, targeting 4–5 mm entry.')+' No qualified torque is specified: snug by hand and stop if plastic compresses, whitening appears, or a seam moves. Recheck after a warm hold; printed plastic creeps.'},
{title:'RF surface and accuracy',body:`Apply continuous conductive foil or a specified conductive coating; see REFLECTOR.md for preparation and source references. Keep flange seats, notches and bores clean. Align before bridging seams with removable foil strips. The parabola focus is ${m.focal.toFixed(2)} mm from the extrapolated vertex, not from the hub back. Frequency does not move that geometric focus. Feed phase-center position, illumination, surface error and pointing determine RF performance. Mesh spacing is a geometric approximation too: reduce it for short wavelengths and measure the final coated dish. No calculated focal point or closed STL establishes measured gain.`},
{title:'Inspection before a full article',body:'Record seam steps and dish profile before tightening, after tightening, at several elevations, and after thermal settling. A key that fits a coupon does not prove a full petal will stay true. Check screw bearing on the flat seats, flange-root cracking, seat flatness and tool access on the test parts. Test repeated assembly and mark screws/rods to reveal movement. Wind, water, UV, creep and transport loads are not qualified. Keep a foil-covered dish away from direct sunlight during handling because it can concentrate heat.'},
...(m.feed?[{title:'Rod support',body:feedGuide(m)}]:[])];}
export const guide=m=>'# PETAL '+VERSION+' — print and assembly\n\n'+guideSections(m).map(x=>'## '+x.title+'\n\n'+x.body).join('\n\n')+'\n';
export function hardwareCSV(m){const q=x=>'"'+String(x??'').replaceAll('"','""')+'"';return'item,specification,quantity,note\n'+hardwareSchedule(m).map(x=>[x.item,x.spec,x.quantity,x.note].map(q).join(',')).join('\n')+'\n';}
export const assemblyPDF=m=>instructionPDF(m,{sections:guideSections(m),reflector:reflectorGuide(m),hardware:hardwareSchedule(m)});
export function kit(m){const entries=m.parts.map(p=>({name:`${p.id}_qty-${p.qty}.stl`,data:binarySTL(p.output)}));for(const c of connectionCoupon(m))entries.push({name:'FIT_TEST/'+c.id+'.stl',data:binarySTL(c.output)});entries.push({name:'FIT_TEST/README.md',data:'Print TWO copies of the seam strip. These retain the real side-print orientation. Bring their neighboring edges together at the dish angle, fit the key and '+(m.p.seamJoint===1?'a clip':m.p.seamJoint?'one M3 screw or a clip':'one M3 screw')+'; do not flatten them against a table.'+(m.p.seamJoint?' The three seam-clip-fit files are the same clip at three squeeze settings (mm per side): print them flat as exported, try each, and set Clip squeeze to the one that clicks firmly without whitening.':'')+' See ASSEMBLY.md.\n'});for(const[ i,plate]of m.plates.entries())if(plate.placements.length)entries.push({name:`PACKED/plate-${i+1}.stl`,data:binarySTL(packedPlateMesh(plate))});entries.push({name:'PLATES.csv',data:'plate,copy,part,x_mm,y_mm,yaw_degrees\n'+m.plates.flatMap((p,i)=>p.placements.map(x=>[i+1,x.copy,x.part.id,x.x,x.y,x.yaw].join(','))).join('\n')},{name:'ASSEMBLY.pdf',data:assemblyPDF(m)},{name:'parameters.json',data:JSON.stringify(manifest(m),null,2)},{name:'ASSEMBLY.md',data:guide(m)},{name:'REFLECTOR.md',data:reflectorGuide(m)},{name:'HARDWARE.csv',data:hardwareCSV(m)},{name:'petal-snapshot.scad',data:scadSource(m)});if(m.feed)entries.push({name:'FEED-SUPPORT.md',data:feedGuide(m)},{name:'RODS.csv',data:rodCSV(m)},{name:'FEED-HARDWARE.csv',data:feedHardwareCSV(m)});return new Blob([zip(entries)],{type:'application/zip'});}
